// GenerateAuthURL generates an OAuth2 authorization URL for the user to authenticate.
// The redirectPath parameter allows customization of where the user should be redirected after auth.
// It does so by storing the redirect path in a secure cookie for later use in the callback handler.
// The session cookie can be used on the callback side to bind the OAuth state to a specific user session.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// Generate a cryptographically secure random state to prevent CSRF
	stateBytes := make([]byte, 32)
	if _, err := rand.Read(stateBytes); err != nil {
		return "", err
	}
	state := base64.RawURLEncoding.EncodeToString(stateBytes)

	// Store the state in a cookie for later validation
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
	})

	// Store the intended post-login redirect path in another cookie
	// (base64-encoded to safely handle any characters)
	encodedRedirect := base64.URLEncoding.EncodeToString([]byte(redirectPath))
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_redirect",
		Value:    encodedRedirect,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
	})

	// Generate the authorization URL using the original registered RedirectURL
	authURL := OAuthConfig.AuthCodeURL(state)

	return authURL, nil
}

