		TokenURL: "https://provider.com/oauth2/token",
	},
}

// getPort returns the port of the URL, defaulting to the standard port for the scheme.
func getPort(u *url.URL) string {
	port := u.Port()
	if port == "" {
		switch u.Scheme {
		case "http":
			port = "80"
		case "https":
			port = "443"
		// for other schemes we leave port empty, requiring an exact match
		}
	}
	return port
}

// GenerateAuthURL generates an OAuth2 authorization URL for the user to authenticate.
// The redirectPath parameter allows customization of where the user should be redirected after auth.
// It can be either an absolute URL (which must match the registered redirect URI's scheme, host and path prefix)
// or a relative path that will be resolved against the registered redirect URI.
// A cryptographically random state is generated per request to protect against CSRF, and this state is
// stored in a secure cookie for later verification.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// Avoid "unused parameter" compile errors.
	_ = session
	_ = r

	// Validate the user-provided redirect URL against the pre-registered redirect URI.
	defaultRedirect, err := url.Parse(OAuthConfig.RedirectURL)
	if err != nil {
		return "", errors.New("internal error: invalid registered redirect URL")
	}

	var redirectURL *url.URL

	// If redirectPath contains a scheme, treat it as an absolute URL.
	if strings.Contains(redirectPath, "://") {
		customURL, err := url.Parse(redirectPath)
		if err != nil {
			return "", errors.New("invalid redirect_path: not a valid URL")
		}
		// Absolute URLs must have a scheme.
		if customURL.Scheme == "" {
			return "", errors.New("invalid redirect_path: must be absolute URL")
		}

		// Scheme comparison (case-insensitive).
		if !strings.EqualFold(customURL.Scheme, defaultRedirect.Scheme) {
			return "", errors.New("invalid redirect_path: does not match allowed redirect URI pattern")
		}

		// Hostname must match exactly.
		if customURL.Hostname() != defaultRedirect.Hostname() {
			return "", errors.New("invalid redirect_path: does not match allowed redirect URI pattern")
		}

		// Port must match, defaulting to the standard port for the scheme.
		if getPort(customURL) != getPort(defaultRedirect) {
			return "", errors.New("invalid redirect_path: does not match allowed redirect URI pattern")
		}

		// Path validation: the custom path must be exactly the registered path
		// or a subpath (to allow deeper routes under the callback prefix).
		defaultPath := path.Clean(defaultRedirect.Path)
		customPath := path.Clean(customURL.Path)

		if defaultPath != "/" {
			if customPath != defaultPath && !strings.HasPrefix(customPath, defaultPath+"/") {
				return "", errors.New("invalid redirect_path: does not match allowed redirect URI pattern")
			}
		}
		redirectURL = customURL
	} else {
		// Relative path: must start with "/".
		if !strings.HasPrefix(redirectPath, "/") {
			return "", errors.New("invalid redirect_path: relative path must start with '/'")
		}
		rel, err := url.Parse(redirectPath)
		if err != nil {
			return "", errors.New("invalid redirect_path: not a valid relative URL")
		}
		resolvedURL := defaultRedirect.ResolveReference(rel)

		// Validate that the resolved path is within the allowed prefix.
		defaultPath := path.Clean(defaultRedirect.Path)
		resolvedPath := path.Clean(resolvedURL.Path)
		if defaultPath != "/" {
			if resolvedPath != defaultPath && !strings.HasPrefix(resolvedPath, defaultPath+"/") {
				return "", errors.New("invalid redirect_path: does not match allowed redirect URI pattern")
			}
		}
		redirectURL = resolvedURL
	}

	// Generate a unique random state to prevent CSRF attacks.
	stateBytes := make([]byte, 16)
	if _, err := rand.Read(stateBytes); err != nil {
		return "", errors.New("failed to generate random state")
	}
	state := hex.EncodeToString(stateBytes)

	// Create a copy of the OAuth config with the validated redirect URL.
	config := *OAuthConfig
	config.RedirectURL = redirectURL.String()

	// Generate the authorization URL.
	authURL := config.AuthCodeURL(state)

	// Store the state in a secure cookie for later verification during the callback.
	http.SetCookie(w, &http.Cookie{
		Name:     "oauth_state",
		Value:    state,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
		Path:     "/",
		MaxAge:   600, // 10 minutes, typical OAuth flow time window
	})

	return authURL, nil
}

