// GenerateAuthURL generates an OAuth2 authorization URL for the user to authenticate.
// The redirectPath parameter allows customization of where the user should be redirected after auth.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// Generate a random state token to prevent CSRF attacks.
	state, err := generateRandomState()
	if err != nil {
		return "", fmt.Errorf("failed to generate state: %w", err)
	}

	// Set the state in a secure cookie that will be checked on callback.
	stateCookie := &http.Cookie{
		Name:     "oauthstate",
		Value:    state,
		Path:     "/",
		HttpOnly: true,
		Secure:   r.TLS != nil,
		SameSite: http.SameSiteLaxMode,
		MaxAge:   600, // 10 minutes
	}
	http.SetCookie(w, stateCookie)

	// Build the authorization URL with optional custom redirect_uri.
	opts := []oauth2.AuthCodeOption{}
	if redirectPath != "" {
		customRedirectURI, err := buildCustomRedirectURI(redirectPath)
		if err != nil {
			return "", fmt.Errorf("invalid redirect path: %w", err)
		}
		opts = append(opts, oauth2.SetAuthURLParam("redirect_uri", customRedirectURI))
	}

	authURL := OAuthConfig.AuthCodeURL(state, opts...)
	return authURL, nil
}

// generateRandomState generates a cryptographically random hex string.
func generateRandomState() (string, error) {
	b := make([]byte, 32)
	_, err := rand.Read(b)
	if err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// buildCustomRedirectURI constructs the full redirect URI from the given path.
// If the redirectPath is a relative path, it combines it with the scheme and host
// of the configured RedirectURL. If it's an absolute URL, it returns it as is.
func buildCustomRedirectURI(redirectPath string) (string, error) {
	u, err := url.Parse(redirectPath)
	if err != nil {
		return "", err
	}
	if u.IsAbs() {
		return redirectPath, nil
	}
	base, err := url.Parse(OAuthConfig.RedirectURL)
	if err != nil {
		return "", fmt.Errorf("invalid configured RedirectURL: %w", err)
	}
	if len(redirectPath) > 0 && redirectPath[0] != '/' {
		redirectPath = "/" + redirectPath
	}
	base.Path = redirectPath
	base.RawQuery = ""
	return base.String(), nil
}

