// validateRedirectPath checks that the requested path is safe and returns a normalised form.
// It accepts a relative path (starting with /) or an absolute URL with the same origin as the base.
func validateRedirectPath(path string, base *url.URL) (string, error) {
	path = strings.TrimSpace(path)
	if path == "" {
		path = "/"
	}

	// If it looks like an absolute URL, ensure it matches the trusted base origin.
	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
