			return "", errors.New("redirect URL must use the same scheme and host as the application")
		}
		// The path is under our control; accept it as-is (already an absolute URL).
		return path, nil
	}

	// Relative path: must start with '/' and must not contain path traversal.
	if !strings.HasPrefix(path, "/") {
