// GenerateAuthURL generates an OAuth2 authorization URL for the user to authenticate.
// The redirectPath parameter allows customization of where the user should be redirected after auth.
func GenerateAuthURL(redirectPath string, session *http.Cookie, w http.ResponseWriter, r *http.Request) (string, error) {
	// Generate a random state for CSRF protection.
	stateBytes := make([]byte, 16)
	if _, err := rand.Read(stateBytes); err != nil {
		return "", fmt.Errorf("failed to generate random state: %w", err)
	}
	state := base64.RawURLEncoding.EncodeToString(stateBytes)

	// Embed the desired post‑login redirect path in the state.
	if redirectPath == "" {
		redirectPath = "/"
	}
	state = fmt.Sprintf("%s:%s", state, redirectPath)

	// Store the state in a cookie so the callback can validate it.
	// If a session cookie was provided, update its value.
	if session != nil {
		session.Value = state
		if session.Path == "" {
			session.Path = "/"
		}
		http.SetCookie(w, session)
	} else {
		// Fallback: create a new cookie if none was supplied.
		cookie := &http.Cookie{
			Name:     "oauthstate",
			Value:    state,
			Path:     "/",
			HttpOnly: true,
			Secure:   r.TLS != nil,
			SameSite: http.SameSiteLaxMode,
		}
		http.SetCookie(w, cookie)
	}

	// Generate the authorization URL using the OAuth2 library.
	authURL := OAuthConfig.AuthCodeURL(state)
	return authURL, nil
}

